ALTER TABLE public.laudo_item_componentes ADD COLUMN ordem_avaliado integer, ADD COLUMN ordem_reaproveitado integer;
UPDATE public.laudo_item_componentes c SET ordem_avaliado=array_position(regexp_split_to_array(coalesce(p->>'itemAvaliado',''),'\s*,\s*'),c.codigo), ordem_reaproveitado=array_position(regexp_split_to_array(coalesce(p->>'itemReaproveitado',''),'\s*,\s*'),c.codigo) FROM public.laudo_itens i JOIN public.laudos l ON l.id=i.laudo_id CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.xml_dados->'produtos','[]')) WITH ORDINALITY a(p,pos) WHERE c.laudo_item_id=i.id AND i.posicao=pos;
CREATE FUNCTION public.ordem_componente_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; BEGIN SELECT l.xml_dados->'produtos'->(i.posicao-1) INTO p FROM public.laudo_itens i JOIN public.laudos l ON l.id=i.laudo_id WHERE i.id=NEW.laudo_item_id; NEW.ordem_avaliado:=array_position(regexp_split_to_array(coalesce(p->>'itemAvaliado',''),'\s*,\s*'),NEW.codigo); NEW.ordem_reaproveitado:=array_position(regexp_split_to_array(coalesce(p->>'itemReaproveitado',''),'\s*,\s*'),NEW.codigo); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.ordem_componente_snapshot() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER componente_ordem BEFORE INSERT OR UPDATE ON public.laudo_item_componentes FOR EACH ROW EXECUTE FUNCTION public.ordem_componente_snapshot();
DO $$ DECLARE v text; BEGIN SELECT pg_get_viewdef('public.laudos_leitura'::regclass,true) INTO v; v:=replace(v,'ORDER BY c.created_at, c.codigo','ORDER BY c.ordem_avaliado, c.codigo'); v:=replace(v,'ORDER BY c.ordem_avaliado, c.codigo) AS string_agg' || chr(10) || '           FROM laudo_item_componentes c' || chr(10) || '          WHERE ((c.laudo_item_id = i.id) AND c.reaproveitado)', 'ORDER BY c.ordem_reaproveitado, c.codigo) AS string_agg' || chr(10) || '           FROM laudo_item_componentes c' || chr(10) || '          WHERE ((c.laudo_item_id = i.id) AND c.reaproveitado)'); EXECUTE 'CREATE OR REPLACE VIEW public.laudos_leitura WITH (security_invoker=true) AS ' || v; END $$;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.salvar_laudo_relacional(uuid,jsonb)'::regprocedure) INTO f; f:=replace(f,$s$ARRAY['conferido','data_conferencia','conferente','conferenteId']$s$,$s$ARRAY['itemId','conferido','data_conferencia','conferente','conferenteId']$s$); f:=replace(f,$s$jsonb_array_elements(coalesce(antigo.xml_dados->'produtos','[]'))$s$,$s$jsonb_array_elements((SELECT produtos FROM public.laudos_leitura WHERE id=p_id))$s$); EXECUTE f; END $$;
COMMENT ON FUNCTION public.salvar_laudo_relacional(uuid,jsonb) IS 'Intentional authenticated SECURITY DEFINER RPC: atomic writes; validates auth.uid, owner/admin and conference-only updates; no anonymous execution. Required because child tables are read-only to callers.';